INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('109bcb35-315f-47ea-b361-1e2488524eaa', 'radical', '广', 'canopy', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah kanopi. Lihat kainnya menjuntai ke bawah dan ujung kecil di tengahnya menahannya? Anda bisa duduk di bawah sini dan menikmati hari musim panas yang cerah tanpa terkena sinar matahari!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('109bcb35-315f-47ea-b361-1e2488524eaa', 'Kanopi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('662563bb-481b-4563-84a4-4a7846817e53', 'radical', '[Pengemis]', 'beggar', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Bukankah ini terlihat seperti seseorang yang berlutut, mengulurkan tangan (bergenggaman) dan memohon sesuatu (uang, nyawa, dll.)? Itu sebabnya kaum radikal ini dikenal dengan sebutan pengemis.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('662563bb-481b-4563-84a4-4a7846817e53', 'Pengemis', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('b7e87ddd-c228-491b-9736-61a6bf599f71', 'radical', '古', 'old', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Mulutmu berbentuk salib—mulut itu cukup religius. Siapa yang paling banyak berbicara tentang agama? Kebanyakan orang tua. Juga, pikirkan tentang ajaran agama itu sendiri - juga cukup tua, berdasarkan usia. Tidak peduli bagaimana Anda melihatnya, segala sesuatu tentang radikal ini sudah “kuno”.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b7e87ddd-c228-491b-9736-61a6bf599f71', 'Tua', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('fc7064fc-7638-45e4-835b-bf3ff46c1491', 'radical', '会', 'meet', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Di bawah topi itu ada dua orang yang bertemu secara pribadi. Lihatlah mereka meringkuk di sana. Mereka pasti punya alasan ingin bertemu di tempat privat seperti itu, tapi itu bukan hak Anda untuk menilai. Mungkin lain kali Anda harus bertemu dengan seseorang, Anda juga akan bersembunyi di bawah topi bersama mereka.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fc7064fc-7638-45e4-835b-bf3ff46c1491', 'Bertemu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('003b7ca6-13f9-4bd2-9982-be9b78e8730b', 'radical', '自', 'self', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Flek/tetesan kecil di matamu itulah yang membuatmu unik. Itulah yang membuatmu menjadi dirimu sendiri. Itu kamu, kamu tahu?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('003b7ca6-13f9-4bd2-9982-be9b78e8730b', 'Diri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('bf18f5dc-3e51-42ab-96c2-cae2da254cb0', 'radical', '冋', 'mustache', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Lihat kumis di sekitar mulut? Saya berharap saya bisa menumbuhkan kumis manis seperti ini.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bf18f5dc-3e51-42ab-96c2-cae2da254cb0', 'Kumis', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('6f54c654-910d-4f3d-95e3-be0537bdc1c7', 'radical', '也', 'alligator', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Lihat mulut dan gigi aligator yang menghadap ke kanan ini? Anda tidak ingin tangan Anda tersangkut di sana, itu sudah pasti.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6f54c654-910d-4f3d-95e3-be0537bdc1c7', 'Buaya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('0d9e36e7-a722-4f03-b487-dd54155e2fb1', 'radical', '歹', 'yakuza', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kelompok radikal malam ada di bawah tanah. Siapa yang melakukan hal-hal di bawah tanah pada malam hari? Yakuza. Bayangkan anggota Yakuza menyelinap di kereta bawah tanah, atau di selokan. Mereka pasti sedang merencanakan sesuatu yang tidak baik di bawah sana.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0d9e36e7-a722-4f03-b487-dd54155e2fb1', 'Yakuza', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('02baaf22-acf6-4946-a897-4b8e657f1452', 'radical', '匕', 'spoon', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Radikal ini terlihat seperti sendok! Nah, sendok yang banyak dibengkokkan oleh orang yang sedang marah atau paranormal. Ambil sendok dan coba tekuk menjadi bentuk ini. Kemudian peganglah agar Anda tidak pernah lupa bahwa ini adalah sendok radikal!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('02baaf22-acf6-4946-a897-4b8e657f1452', 'sendok', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('8d96cc02-008d-4795-bad2-4d4f84d39025', 'radical', '耂', 'coffin', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Lihat slidenya masuk ke tanah? Di situlah mereka membuang tubuhmu saat kamu mati. Ini sebenarnya peti mati!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8d96cc02-008d-4795-bad2-4d4f84d39025', 'Peti mati', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('9b111d27-48ef-4287-b61a-9dddbb0e7516', 'radical', '宀', 'roof', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah atap. Anda tahu itu atap dan bukan dahi karena ada cerobong kecil yang mencuat dari atasnya. Dan dahi pastinya tidak mempunyai cerobong asap.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9b111d27-48ef-4287-b61a-9dddbb0e7516', 'Atap', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('6a017a44-e9b4-40f5-a8aa-31f4740f4da5', 'radical', '色', 'color', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Tempat tidur yang Anda dapatkan di penjara adalah satu-satunya warna yang akan Anda lihat saat berada di sana. Bayangkan sebuah sel yang gelap dan lembap. Mungkin toilet juga. Sekarang bayangkan tempat tidur yang cerah dan berwarna-warni menempel di dinding. Inilah satu-satunya kebahagiaan yang Anda miliki.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6a017a44-e9b4-40f5-a8aa-31f4740f4da5', 'Warna', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('85b3c535-4c7c-4fd2-9806-2e4e1db204db', 'radical', '肉', 'meat', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Di dalam kepala Anda, Anda hanya bisa memikirkan orang, orang, dan lebih banyak orang. Ini buruk, karena yang kamu inginkan hanyalah daging mereka, karena kamu adalah sejenis kanibal yang sakit... dasar monster. Ketika Anda memikirkan "orang" di kepala Anda, Anda sebenarnya hanya memikirkan tentang lebih banyak daging yang bisa Anda makan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('85b3c535-4c7c-4fd2-9806-2e4e1db204db', 'Daging', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('14f0d720-ede2-4b19-ba2e-3a83c19fc566', 'radical', '乍', 'key', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah kunci yang bentuknya sangat aneh, tapi tetap saja ini adalah kunci.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('14f0d720-ede2-4b19-ba2e-3a83c19fc566', 'Kunci', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('6bdf0f7d-eae0-49a1-a101-e615911b6e62', 'radical', '禾', 'grain', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah pohon dengan slide yang memotong bagian atasnya. Dengan apa Anda memotong bagian atas pohon dan tanaman? Biji-bijian. Bayangkan mengambil sabit dan mengiris butiran beras atau gandum. Tanaman yang Anda tinggalkan akan terlihat radikal seperti ini. Itu tandanya kamu mendapat semacam butiran darinya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6bdf0f7d-eae0-49a1-a101-e615911b6e62', 'Gandum', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('4aae2400-4f20-4cde-83df-ec20c82174d7', 'radical', 'ネ', 'spirit', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini terlihat seperti karakter katakana untuk ne. Bukan untuk ahli nujum! Itu menjadikannya roh, yang dibangkitkan dari kubur. OooooOOooooOoo!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4aae2400-4f20-4cde-83df-ec20c82174d7', 'Semangat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('8e475e89-af31-4d84-a596-8d4fb2c37829', 'radical', '刂', 'knife', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah pisau. Lihat bagaimana ia memiliki dua sisi yang tajam? Dan ada pegangan kecil di bagian bawah untuk... yah pegangannya. Hati-hati jangan sampai melukai diri sendiri!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8e475e89-af31-4d84-a596-8d4fb2c37829', 'Pisau', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('110deca9-1ec1-4543-bdbd-248f1d551712', 'radical', '⻌', 'scooter', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Radikal ini adalah skuter. Lihat stang dan lampu kecilnya? Dan ada platform di bagian bawah tempat Anda dapat berdiri atau duduk (jika itu salah satu platform bermotor yang bagus).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('110deca9-1ec1-4543-bdbd-248f1d551712', 'Skuter', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('86b3f9a3-1e99-4745-8aa4-a3881a8a8bb3', 'radical', '斤', 'axe', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Saya tahu, ini kapak yang tampak aneh. Tapi coba pikirkan seperti ini: huruf "T" ada di tebing. Apa itu "T"? Tentu saja harus Pak T yang super hebat. Bayangkan Tuan T yang memegang kapak yang menakutkan, berlari mengejar Anda sambil berteriak, "Kasihan sekali orang bodoh itu!" sambil mencoba menebasmu. Itu menghasilkan kapak yang cukup menakutkan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('86b3f9a3-1e99-4745-8aa4-a3881a8a8bb3', 'Kapak', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f3054be3-2053-4ef7-a4c1-bcebe0aaefd0', 'radical', '足', 'foot', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Apakah Anda melihat pria itu melakukan tendangan naga terbang ke kanan? Dengan apa dia mencapai target? Jelas itu adalah kakinya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f3054be3-2053-4ef7-a4c1-bcebe0aaefd0', 'Kaki', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('205feb54-24cb-4604-8d4d-5e752f320441', 'kanji', '去', '去', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Jika seseorang mencoba menggali rahasia pribadi Anda, katakan tidak, terima kasih, itu sudah berlalu. Beberapa hal harus tetap menjadi masa lalu. Tidak semua orang perlu mengetahui segalanya tentang kehidupan dan masa lalu Anda.', 'Untuk mengingat bacaan きょ, kita akan menggunakan "Kyoto Kecil". Ini akan membedakan きょ dari きょう, yang merupakan Kyoto berukuran biasa. Mengerti? Anda memutuskan untuk mengubur semua kotoran pribadi dari masa lalu Anda di Little Kyoto (きょ). Hal itu berasal dari saat kamu masih kecil 子 (こ) dan kamu tidak suka memikirkannya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('205feb54-24cb-4604-8d4d-5e752f320441', 'Masa lalu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('205feb54-24cb-4604-8d4d-5e752f320441', 'きょ', 'onyomi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('205feb54-24cb-4604-8d4d-5e752f320441', 'こ', 'onyomi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('205feb54-24cb-4604-8d4d-5e752f320441', 'さ', 'kunyomi', false) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('8876edc5-41bb-4478-9fd9-9ab384f7deb2', 'kanji', '広', '広', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kanopi yang Anda gunakan secara pribadi sangat lebar.', 'Anda suka bersikap lebar karena itu membuat Anda merasa seperti orang yang berbeda. Tapi bukan sembarang orang, seperti pahlawan super (ひろ)!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8876edc5-41bb-4478-9fd9-9ab384f7deb2', 'Lebar', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8876edc5-41bb-4478-9fd9-9ab384f7deb2', 'こう', 'onyomi', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8876edc5-41bb-4478-9fd9-9ab384f7deb2', 'ひろ', 'kunyomi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('f88dfc1a-284f-4117-8d5d-8bff7bb46e15', 'kanji', '写', '写', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Pengemis itu mengarahkan dahinya ke arah Anda, kakinya tertancap di tanah. Skema jahat apa yang kamu rencanakan dengan pengemis malang yang kamu jebak ini? Ternyata, Anda berencana untuk menirunya agar memiliki versi Anda sendiri.', 'Untuk mengingat bacaan しゃ, kita menggunakan kata "dukun".
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f88dfc1a-284f-4117-8d5d-8bff7bb46e15', 'Salin', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f88dfc1a-284f-4117-8d5d-8bff7bb46e15', 'しゃ', 'onyomi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f88dfc1a-284f-4117-8d5d-8bff7bb46e15', 'うつ', 'kunyomi', false) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('be7b7c13-8c99-45ed-ac0a-632e895a9a01', 'kanji', '古', '古', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kanji dan radikalnya sama, jadi mengingat arti kanji ini semudah memastikan Anda mengetahui radikalnya terlebih dahulu! Jika Anda tahu radikalnya, Anda pasti tahu kanji ini artinya tua juga.
