INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('72d9015a-283b-4ede-a2f4-afd65001dc7f', 'kanji', '兄', '兄', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Siapakah seseorang yang hanya bermulut dan berkaki? Itu adalah kakak laki-lakimu yang sok tahu, yang tidak akan tutup mulut tentang apa pun.', 'Kamu berharap bisa mengurung kakak laki-lakimu yang suka bermulut keras dan mengirimnya jauh ke きょうと. Lokasinya sangat jauh dari tempat tinggalmu saat ini, jadi kirimkan saja kakakmu agar dia tidak mengganggumu lagi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
