INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('65c6851b-7081-47a0-8059-ee9618433ee9', 'kanji', '冬', '冬', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kita punya musim dingin yang radikal dan dua radikal (walaupun agak miring). Apa artinya dua kali radikal musim dingin, jika radikal hanyalah bagian dari kanji? Dua kali sudah cukup untuk membuat seluruh kanji, yang juga merupakan musim dingin.', 'Musim dingin adalah waktu di mana kamu membagikan hadiah: "satu untukmu, satu untukmu. Dan... bukan kamu, yang ini bukan untukmu, jadi fu’ kamu! (ふゆ)!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
