INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('bd3e3324-b7ba-49f1-bc11-4d725d37b0ed', 'kanji', '体', '体', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Pemimpinnya memiliki buku tentang tubuh manusia. Mengetahui tentang tubuh adalah suatu kehormatan. Sesuatu yang hanya dimiliki oleh para pemimpin—ini membantu mereka mengendalikan seluruh rakyatnya, seperti Anda.', 'Buku tubuh pemimpin juga mengajarinya tentang sesuatu yang sangat spesifik pada tubuh: cara mengikat dasi (たい). Kau tidak boleh memakai dasi di tubuhmu, tidak, tidak. Itu untuk pemimpin dan tubuh cerdasnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
