INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('8e3d0b44-43f1-4ff8-b6ee-6d1e4195164a', 'kanji', '近', '近', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Seseorang yang mengendarai skuter memiliki kapak, dan mereka mendekati Anda dengan sangat cepat! Oh tidak, mereka sudah sangat dekat sekarang, kamu harus keluar dari sini!', 'Saat mereka mendekat, Anda mengenali siapa yang mengendarai skuter: Raja (きん) Inggris! Di belakangnya, sekelompok pengawalnya yang juga mengendarai skuter dan memegang kapak muncul dan bergerak mendekati Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
