INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e0227c6-891e-4e33-af87-cf37a362c437', '山下さんはわたしの兄ににていますね。', 'Anda terlihat seperti kakak laki-laki saya, Tuan Yamashita.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e0227c6-891e-4e33-af87-cf37a362c437', '一ヶ月まえに兄がくろラブをつれていえにかえってきました。', 'Sebulan yang lalu, kakak laki-laki saya pulang dengan membawa seekor labrador hitam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e0227c6-891e-4e33-af87-cf37a362c437', '兄は、とうふにコーヒーをかけてたべるのがすきだ。', 'Kakak laki-lakiku suka makan tahu yang dilumuri kopi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6a8ec0b2-29e2-4b19-b9f7-a9ccc38f54a7', 'vocabulary', 'お兄さん', 'お兄さん', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kata ini diawali dengan お agar lebih sopan. Lalu ada kanji 兄 yang sudah Anda ketahui. Terakhir, ada さん yang merupakan suatu kehormatan untuk meninggikan orang dan bersikap sopan. Ini pada dasarnya adalah cara formal untuk mengucapkan kakak laki-laki (versus kata tua biasa 兄). Ini juga bisa digunakan untuk merujuk pada pria yang tidak Anda kenal yang memiliki penampilan awet muda.', 'Kata ini diawali dengan お agar lebih sopan. Lalu ada kanji 兄 yang sudah Anda ketahui. Terakhir, ada さん yang merupakan suatu kehormatan untuk meninggikan orang dan bersikap sopan. Ini pada dasarnya adalah cara formal untuk mengucapkan kakak laki-laki (versus kata tua biasa 兄). Ini juga bisa digunakan untuk merujuk pada pria yang tidak Anda kenal yang memiliki penampilan awet muda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
