INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a8ec0b2-29e2-4b19-b9f7-a9ccc38f54a7', 'どれがたかしのお兄さんですか。', 'Yang mana kakak laki-laki Takashi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a8ec0b2-29e2-4b19-b9f7-a9ccc38f54a7', '今日のたっきゅうびんのお兄さんのかおがタイプすぎた。', 'Pengantar barang hari ini memiliki tipe wajah yang persis seperti yang saya inginkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a8ec0b2-29e2-4b19-b9f7-a9ccc38f54a7', 'お兄さんのはなげがきになってしかたがない。', 'Mau tak mau aku memikirkan bulu hidung kakak laki-lakiku.') ON CONFLICT DO NOTHING;
