INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2685a800-3d32-4359-9146-5b25f73f06b0', 'ことしの冬は、ゆきがたくさんふりました。', 'Musim dingin ini turun banyak salju.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2685a800-3d32-4359-9146-5b25f73f06b0', 'きょねんの冬にかいたえです。', 'Ini adalah ilustrasi yang saya gambar musim dingin lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2685a800-3d32-4359-9146-5b25f73f06b0', '冬をなめるといたい目にあうぞ！', 'Jangan meremehkan musim dingin atau Anda pasti akan mengalami pengalaman yang menyakitkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4b84fc36-fe60-4d28-84c0-291ae0528a95', 'vocabulary', '古い', '古い', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari lama? Itu juga tua, kuno, atau ketinggalan jaman.
