INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('83e0e067-23de-41d0-ac0f-df089a7dd5ad', '中古ですが、ベンツをかいました。', 'Itu bekas, tapi saya membeli Benz.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('83e0e067-23de-41d0-ac0f-df089a7dd5ad', 'このあたりは、中古ショップがじゅうじつしています。', 'Ada banyak toko barang bekas di daerah ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('83e0e067-23de-41d0-ac0f-df089a7dd5ad', '中古のかぐのような人とはけっこんしたくない。', 'Saya tidak ingin menikah dengan seseorang yang seperti perabot bekas.') ON CONFLICT DO NOTHING;
