INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('efebba90-440b-4eb6-9bc2-c64dbd27ea91', '友だちのへやは、広くてきれいです。', 'Kamar teman saya luas dan bersih.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('efebba90-440b-4eb6-9bc2-c64dbd27ea91', 'あのフランス人はおでこが広い。', 'Orang Perancis itu mempunyai dahi yang lebar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('efebba90-440b-4eb6-9bc2-c64dbd27ea91', 'すげー広いな！', 'Wah, tempat ini sangat besar!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0fd64212-b1f8-4426-b8b2-4cf00a40dca9', 'vocabulary', '名字', '名字', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Nama yang ditulis dengan huruf adalah nama keluarga. Dulu, nama belakang Anda adalah nama yang penting (bagaimanapun juga itu adalah nama keluarga Anda, dan keluarga adalah raja pada masa itu). Ini adalah nama yang akan kamu tulis dalam kanji... alias dalam huruf. Jadi itulah mengapa kombinasi kanji ini berarti "nama keluarga".', 'Nama yang ditulis dengan huruf adalah nama keluarga. Dulu, nama belakang Anda adalah nama yang penting (bagaimanapun juga itu adalah nama keluarga Anda, dan keluarga adalah raja pada masa itu). Ini adalah nama yang akan kamu tulis dalam kanji... alias dalam huruf. Jadi itulah mengapa kombinasi kanji ini berarti "nama keluarga".') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0fd64212-b1f8-4426-b8b2-4cf00a40dca9', 'Nama keluarga', true) ON CONFLICT DO NOTHING;
