INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c70b0764-350b-4522-a615-efb481403211', '文字はきいろにしてください。', 'Tolong jadikan surat ini kuning.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c70b0764-350b-4522-a615-efb481403211', 'マイケルは八じかんかけてコウイチにしょうけい文字で手がみをしたためた。', 'Michael membutuhkan waktu delapan jam untuk menulis surat kepada Koichi dalam huruf hieroglif.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c70b0764-350b-4522-a615-efb481403211', 'あなたからのメール、文字化けしちゃったみたいなんだけど、何て書いてたの？', 'Sepertinya email dari Anda berisi karakter yang rusak, apa yang Anda tulis?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9d426aef-e6e4-41e9-af92-0b4c73e79b5b', 'vocabulary', '一文字', '一文字', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ketika Anda memiliki satu surat tulisan, apa yang Anda miliki? Ini petunjuknya, ada satu kanji di kata ini yang terdiri dari satu huruf tulisan (alias garis lurus).', 'Ketika Anda memiliki satu surat tulisan, apa yang Anda miliki? Ini petunjuknya, ada satu kanji di kata ini yang terdiri dari satu huruf tulisan (alias garis lurus).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9d426aef-e6e4-41e9-af92-0b4c73e79b5b', 'Garis Lurus', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9d426aef-e6e4-41e9-af92-0b4c73e79b5b', 'いちもんじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9d426aef-e6e4-41e9-af92-0b4c73e79b5b', '女の子は、おこって口を一文字にむすびました。', 'Gadis itu marah dan mulutnya membentuk garis lurus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9d426aef-e6e4-41e9-af92-0b4c73e79b5b', 'ペーパータオルでさかなの水気をふきとったら、かわに一文字の切り目を入れてください。', 'Setelah menyeka kelembapan ikan dengan tisu, gores kulitnya secara lurus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9d426aef-e6e4-41e9-af92-0b4c73e79b5b', '白鳥たちは、うちの風呂場からその湖へ、真一文字になって飛んでいった。', 'Angsa-angsa itu terbang lurus dari bak mandi kami ke danau.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2ffbe878-636e-432c-a267-9712bcf184b8', 'vocabulary', '大文字', '大文字', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda memiliki surat tulisan yang besar. Menurut Anda apa ini? ITU HARUS HURUF BESAR, KAN? Ups, maaf, caps lock aktif sebentar, itu.', 'Anda memiliki surat tulisan yang besar. Menurut Anda apa ini? ITU HARUS HURUF BESAR, KAN? Ups, maaf, caps lock aktif sebentar, itu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
