INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c9f9aa7b-b281-434a-a61f-e97d6e4907f8', '去年の四月に日本にきました。', 'Saya datang ke Jepang pada bulan April tahun lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c9f9aa7b-b281-434a-a61f-e97d6e4907f8', '去年、はじめて夏コミにさんせんしました。', 'Tahun lalu, saya pertama kali mengikuti Summer Comiket.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c9f9aa7b-b281-434a-a61f-e97d6e4907f8', '彼はハンバーガーを毎日食べるので、去年よりも太ってしまった。', 'Dia lebih gemuk dibandingkan tahun lalu karena dia makan hamburger setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4b36b063-116b-4e80-aeec-9f4dde0072ca', 'vocabulary', '早い', '早い', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat awal? Ini juga masih pagi.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat awal? Ini juga masih pagi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
