INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b8c04a52-effd-41cc-9b28-a517b84c8377', 'これだけで、足りるのかな。', 'Aku ingin tahu apakah sebanyak ini cukup.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b8c04a52-effd-41cc-9b28-a517b84c8377', 'モナコの王女はせけんしらずなので、車をかうのに十万円もあれば足りるとおもっている。', 'Karena putri di Monaco tidak mengetahui banyak hal, dia berpikir 100.000 yen cukup untuk membeli mobil.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b8c04a52-effd-41cc-9b28-a517b84c8377', '今夜、ワインコルクで何か工作をするのに足りるだけのワインを飲むことを誓います。', 'Saya bersumpah untuk minum cukup anggur untuk membuat sesuatu yang rumit dengan gabusnya malam ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('61f4657f-8085-4a26-ab6b-ff96081dfbaf', 'vocabulary', '足', '足', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kanji dan kata-katanya hampir persis sama. Itu berarti mereka juga berbagi makna. Kaki tetaplah kaki, tahu?', 'Kanji dan kata-katanya hampir persis sama. Itu berarti mereka juga berbagi makna. Kaki tetaplah kaki, tahu?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
