INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61f4657f-8085-4a26-ab6b-ff96081dfbaf', '足にタトゥーがある。', 'Saya memiliki tato di kaki saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61f4657f-8085-4a26-ab6b-ff96081dfbaf', 'わたしは子どものとき、手のことを足、足のことを手だとおもっていました。', 'Ketika saya masih kecil, saya mengira tangan adalah kaki dan kaki adalah tangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61f4657f-8085-4a26-ab6b-ff96081dfbaf', 'もし私が足を切り落としても、すぐにまた生えてくるんだよね？', 'Kalau saya potong kaki saya akan segera tumbuh kembali kan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('da335c6e-ab2a-4bd8-9fe4-aaec4105a3bc', 'vocabulary', '不足', '不足', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda memiliki sesuatu yang tidak cukup. Ketika ada sesuatu yang tidak mencukupi, Anda mengalami kekurangan. Perlu diingat bahwa ini adalah kekurangan fisik, bukan kekurangan kemampuan mental atau semacamnya. Untuk mengingat hal ini, coba pikirkan bagaimana 足 juga berarti "kaki". Apa itu kaki? Sesuatu yang bersifat fisik. Itu sebabnya ini adalah kekurangan fisik.', 'Anda memiliki sesuatu yang tidak cukup. Ketika ada sesuatu yang tidak mencukupi, Anda mengalami kekurangan. Perlu diingat bahwa ini adalah kekurangan fisik, bukan kekurangan kemampuan mental atau semacamnya. Untuk mengingat hal ini, coba pikirkan bagaimana 足 juga berarti "kaki". Apa itu kaki? Sesuatu yang bersifat fisik. Itu sebabnya ini adalah kekurangan fisik.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
