INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6d2b7ac0-e461-4fc0-bd1a-d635e5e87542', 'あなたのお兄さんは、このしゃしんに写っていますか。', 'Apakah saudaramu ada di foto-foto ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6d2b7ac0-e461-4fc0-bd1a-d635e5e87542', '今年とった五百まいの写しんの内、なんと百三まいの写しんに去年しんだ父のすがたが写っていた。', 'Di antara 500 foto yang saya ambil tahun ini, 103 di antaranya menampilkan ayah saya yang meninggal tahun lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6d2b7ac0-e461-4fc0-bd1a-d635e5e87542', 'この写真に写っている男の人は、私のファーストキスです。', 'Pria di foto ini adalah ciuman pertamaku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2c360e40-ee86-43fc-b825-f940909e9825', 'vocabulary', '大会', '大会', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Saat Anda mengadakan pertemuan besar, ada banyak orang yang berkumpul. Mengapa Anda mengumpulkan banyak orang? Mungkin untuk konvensi atau semacam turnamen atau acara.', 'Saat Anda mengadakan pertemuan besar, ada banyak orang yang berkumpul. Mengapa Anda mengumpulkan banyak orang? Mungkin untuk konvensi atau semacam turnamen atau acara.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
