INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2c360e40-ee86-43fc-b825-f940909e9825', '日よう日は、サッカーの大会に出じょうします。', 'Saya berpartisipasi dalam turnamen sepak bola pada hari Minggu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2c360e40-ee86-43fc-b825-f940909e9825', '花火大会では、アイスクリームがよく売れます。', 'Di acara kembang api, es krim laris manis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2c360e40-ee86-43fc-b825-f940909e9825', '私がマラソン大会で優勝したのは、オナラを止めることができず、他のランナーがその臭いを嗅ぐたびにペースを落としていったからだ。', 'Saya memenangkan maraton karena saya tidak bisa berhenti kentut dan semua pelari lainnya melambat setiap kali mereka mencium baunya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7aaab382-385b-4859-a8e7-f4eb67b20436', 'vocabulary', '会う', '会う', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bertemu jadi bentuk kata kerjanya yaitu bertemu atau menjumpai.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bertemu jadi bentuk kata kerjanya yaitu bertemu atau menjumpai.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
