INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3299fee-acb8-4723-913e-c7d7b17f8465', '毎日、同じ人に会います。', 'Saya bertemu orang yang sama setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3299fee-acb8-4723-913e-c7d7b17f8465', '今回のしけんは、ぜん回とほぼ同じ内ようでした。', 'Ujian ini memiliki pertanyaan yang hampir sama seperti sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3299fee-acb8-4723-913e-c7d7b17f8465', 'あの店と同じ味のラーメンがどうしても作りたいんだ。', 'Aku ingin membuat ramen yang rasanya sama dengan yang ada di toko itu, apa pun yang terjadi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bb0115d2-fa71-4861-a6ea-2f15e828ab06', 'vocabulary', '同日', '同日', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda memiliki hari yang sama, yang keluar pada hari yang sama.', 'Anda memiliki hari yang sama, yang keluar pada hari yang sama.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bb0115d2-fa71-4861-a6ea-2f15e828ab06', 'Hari yang Sama', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bb0115d2-fa71-4861-a6ea-2f15e828ab06', 'The Same Day', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bb0115d2-fa71-4861-a6ea-2f15e828ab06', 'どうじつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bb0115d2-fa71-4861-a6ea-2f15e828ab06', 'それらは、同日にはつばいされました。', 'Itu diluncurkan pada hari yang sama.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bb0115d2-fa71-4861-a6ea-2f15e828ab06', 'すきなバンドのライブがちがうはこで同日にかぶっていて、どれにいこうかちょうぜつまよっています。', 'Band yang saya suka mengadakan konser di klub musik yang berbeda pada hari yang sama dan saya benar-benar tidak yakin harus datang ke klub mana.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bb0115d2-fa71-4861-a6ea-2f15e828ab06', '父の死と同日に、アポロ11号が月面着陸に成功した。', 'Di hari yang sama dengan kematian ayah saya, Apollo 11 berhasil mendarat di permukaan bulan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5705e2fb-70a5-4e67-a508-1ede7d386b22', 'vocabulary', '多い', '多い', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari banyak? Jumlahnya juga banyak (atau bisa dibilang banyak). Ngomong-ngomong, ada banyak sekali kanji yang harus dipelajari ya?', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari banyak? Jumlahnya juga banyak (atau bisa dibilang banyak). Ngomong-ngomong, ada banyak sekali kanji yang harus dipelajari ya?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5705e2fb-70a5-4e67-a508-1ede7d386b22', 'Banyak', true) ON CONFLICT DO NOTHING;
