INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ca73d80-942b-4913-af7b-9211d6fe9348', 'ちゃんと自分でしゅくだいをしました。', 'Saya menyelesaikan pekerjaan rumah saya sendiri dengan sempurna.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ca73d80-942b-4913-af7b-9211d6fe9348', '自分に自しんがないとえらべない色だよね。', 'Itu warna yang hanya bisa kamu pilih jika kamu percaya diri dengan dirimu sendiri, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ca73d80-942b-4913-af7b-9211d6fe9348', 'もちろん私は自分と話しますよ。だって、時には専門家の意見が必要ですもの。', 'Tentu saja aku berbicara pada diriku sendiri. Terkadang saya membutuhkan nasihat ahli.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ac83ab1f-416c-4db5-bb29-d1710df75c5c', 'vocabulary', '自立', '自立', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda mampu berdiri dengan menggunakan diri Anda sendiri. Tidak ada yang membantu Anda. Tidak ada yang menahanmu. Ini adalah kemerdekaan Anda!', 'Anda mampu berdiri dengan menggunakan diri Anda sendiri. Tidak ada yang membantu Anda. Tidak ada yang menahanmu. Ini adalah kemerdekaan Anda!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
