INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ab0218f-5bc2-46e6-8f85-ce0de46c16ae', '何色がすきですか。', 'Warna apa yang kamu suka?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ab0218f-5bc2-46e6-8f85-ce0de46c16ae', 'ピーマンはうれるとみどり色から赤色になります。', 'Paprika berubah warna dari hijau menjadi merah saat matang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ab0218f-5bc2-46e6-8f85-ce0de46c16ae', '僕は色盲なので、赤色はオレンジ色に、青色は黒色のように見えます。', 'Saya buta warna, jadi warna merah saya tampak oranye dan biru tampak hitam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3d00ada4-519f-4421-bcaa-b4aa4e3cbcf4', 'vocabulary', '色々', '色々', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah warna kanji yang diulang dua kali (karakter 々 hanya mengulang kanji sebelumnya). Ketika Anda memiliki warna dan warna dan warna, Anda memiliki banyak variasi. Itu sebabnya kata ini mempunyai arti bermacam-macam.', 'Ini adalah warna kanji yang diulang dua kali (karakter 々 hanya mengulang kanji sebelumnya). Ketika Anda memiliki warna dan warna dan warna, Anda memiliki banyak variasi. Itu sebabnya kata ini mempunyai arti bermacam-macam.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
