INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3d00ada4-519f-4421-bcaa-b4aa4e3cbcf4', '色々な小せつをよみました。', 'Saya telah membaca berbagai jenis novel.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3d00ada4-519f-4421-bcaa-b4aa4e3cbcf4', '色々考えたけっか、日よう日にたこやきパーティーをすることにしました。', 'Setelah memikirkan berbagai hal, aku memutuskan untuk mengadakan pesta takoyaki pada hari Minggu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3d00ada4-519f-4421-bcaa-b4aa4e3cbcf4', '私のベッドの下に住んでいるトロールには色々な種類がいます。', 'Ada berbagai spesies troll yang hidup di bawah tempat tidurku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1bc4a883-7b30-4dd8-9686-dbd2aefc1371', 'vocabulary', '水色', '水色', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda mungkin berpikir bahwa warna air ada hubungannya dengan cat air, tetapi ternyata tidak. Tidak, ini ada hubungannya dengan warna air, yang ironisnya dalam bahasa Inggris adalah biru langit. Biru muda juga bisa digunakan.', 'Anda mungkin berpikir bahwa warna air ada hubungannya dengan cat air, tetapi ternyata tidak. Tidak, ini ada hubungannya dengan warna air, yang ironisnya dalam bahasa Inggris adalah biru langit. Biru muda juga bisa digunakan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
