INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1bc4a883-7b30-4dd8-9686-dbd2aefc1371', 'あの水色のバッグがほしいんですが。', 'Saya ingin tas biru muda itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1bc4a883-7b30-4dd8-9686-dbd2aefc1371', 'トーフグのTシャツは、さわやかな水色です。', 'Kaos Tofugu berwarna biru langit yang sejuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1bc4a883-7b30-4dd8-9686-dbd2aefc1371', 'どうして今日の空は水色なんだろう？', 'Mengapa langit hari ini berwarna biru muda?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5312bdac-8898-451f-bac3-553433582dcf', 'vocabulary', '作る', '作る', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya membuat. Bentuk kata kerjanya adalah membuat.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya membuat. Bentuk kata kerjanya adalah membuat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
