INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5312bdac-8898-451f-bac3-553433582dcf', '今日は、ばんごはんにやきそばを作ります。', 'Hari ini, saya akan membuat yakisoba untuk makan malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5312bdac-8898-451f-bac3-553433582dcf', 'フェイスブックのアカウントをふくすう作る方ほうをおしえてください。', 'Bisakah Anda mengajari saya cara membuat banyak akun Facebook?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5312bdac-8898-451f-bac3-553433582dcf', 'テスラ・コイルをどうやって作るのかを知っていたら良かったんだけどな。', 'Saya berharap saya tahu cara membuat kumparan Tesla.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bee3cbdc-8467-4d9e-a7e8-a1e18d3d9946', 'vocabulary', '体', '体', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bee3cbdc-8467-4d9e-a7e8-a1e18d3d9946', 'Tubuh', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bee3cbdc-8467-4d9e-a7e8-a1e18d3d9946', 'からだ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bee3cbdc-8467-4d9e-a7e8-a1e18d3d9946', 'おふろに入ると、はじめに体をあらいます。', 'Saat aku mandi, aku membasuh badanku terlebih dahulu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bee3cbdc-8467-4d9e-a7e8-a1e18d3d9946', 'ジャマルって何でそんなに体がやわらかいの？', 'Jamal, kenapa tubuhmu begitu fleksibel?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bee3cbdc-8467-4d9e-a7e8-a1e18d3d9946', 'なぜだか、体中がかゆいんだ。', 'Seluruh tubuh saya sangat gatal karena suatu alasan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a68839af-8c41-4538-bb27-7a5e4ff66017', 'vocabulary', '体力', '体力', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda memiliki kekuatan tubuh Anda. Ini hanyalah cara lain untuk mengatakan kekuatan fisik. Hati-hati, jika Anda menggunakan terlalu banyak kekuatan fisik, Anda mungkin kehabisan stamina dan daya tahan fisik sepenuhnya! Mereka terikat bersama, jadi pastikan untuk mengatur kecepatan Anda sendiri.', 'Anda memiliki kekuatan tubuh Anda. Ini hanyalah cara lain untuk mengatakan kekuatan fisik. Hati-hati, jika Anda menggunakan terlalu banyak kekuatan fisik, Anda mungkin kehabisan stamina dan daya tahan fisik sepenuhnya! Mereka terikat bersama, jadi pastikan untuk mengatur kecepatan Anda sendiri.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a68839af-8c41-4538-bb27-7a5e4ff66017', 'Kekuatan Fisik', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a68839af-8c41-4538-bb27-7a5e4ff66017', 'Physical Power', false) ON CONFLICT DO NOTHING;
