INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a68839af-8c41-4538-bb27-7a5e4ff66017', 'Endurance', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a68839af-8c41-4538-bb27-7a5e4ff66017', 'たいりょく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a68839af-8c41-4538-bb27-7a5e4ff66017', 'わたしは体力があまりありません。', 'Saya praktis tidak memiliki kekuatan fisik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a68839af-8c41-4538-bb27-7a5e4ff66017', 'コウイチには、うで立てふせを八十回する体力はありません。', 'Koichi tidak memiliki stamina untuk melakukan 80 push-up.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a68839af-8c41-4538-bb27-7a5e4ff66017', 'その熱が彼の体力を弱めたが、まだ自分で水を飲む体力は残っていた。', 'Demamnya melemahkan tubuhnya, namun ia masih cukup kuat untuk minum air sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0ec47f2a-ece0-4930-b9de-3c3eb36a862f', 'vocabulary', '作文', '作文', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Saat Anda membuat tulisan, apa yang Anda lakukan? Sederhananya, Anda sedang menulis. Kalau mau lebih menarik, bisa dibilang ini komposisi.', 'Saat Anda membuat tulisan, apa yang Anda lakukan? Sederhananya, Anda sedang menulis. Kalau mau lebih menarik, bisa dibilang ini komposisi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
