INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e412bb0f-4ca9-404d-941f-86c40ac97493', '工作はとくいではありません。', 'Kerajinan tangan bukanlah kelebihan saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e412bb0f-4ca9-404d-941f-86c40ac97493', 'アリバイ工作にしっぱいした。', 'Saya gagal membuat alibi yang masuk akal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e412bb0f-4ca9-404d-941f-86c40ac97493', '私は小学生の頃、夏休みの自由工作の宿題で、アイスクリームを作る機械を作った。', 'Ketika saya masih di sekolah dasar, saya membuat mesin yang membuat es krim untuk proyek kerajinan sekolah saya selama liburan musim panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('47f54492-5576-4249-92be-2840b138363c', 'vocabulary', '大作', '大作', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Hasil besar! Apa penghasilan besar Anda? Lebih besar dari apa pun. Itu adalah epik Anda (seperti dalam epik yang Anda tulis). Bisa juga berupa kisah yang epik, epik, dan mahakarya.', 'Hasil besar! Apa penghasilan besar Anda? Lebih besar dari apa pun. Itu adalah epik Anda (seperti dalam epik yang Anda tulis). Bisa juga berupa kisah yang epik, epik, dan mahakarya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
