INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47f54492-5576-4249-92be-2840b138363c', 'このえいがは、ヒッチコックの大作だ。', 'Film ini adalah epik Hitchcock.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47f54492-5576-4249-92be-2840b138363c', '今世き一ばんの大作ともいわれているえいがのタイトルは「フグの一生」です。', 'Judul film paling epik abad ini konon adalah, "A Life of Fugu".') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47f54492-5576-4249-92be-2840b138363c', 'ベートーベンが作曲した曲は、どれも大作だった。', 'Setiap musik yang ditulis Beethoven adalah sebuah mahakarya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ffc99a15-facc-4c1b-ae37-6a5a99886144', 'vocabulary', '古来', '古来', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Jika Anda datang ke pesta dengan mengenakan sesuatu yang sangat-sangat tua, semua orang akan tahu bahwa Anda berasal dari zaman kuno (seolah-olah kerutan Anda belum menunjukkannya, bukan?).', 'Jika Anda datang ke pesta dengan mengenakan sesuatu yang sangat-sangat tua, semua orang akan tahu bahwa Anda berasal dari zaman kuno (seolah-olah kerutan Anda belum menunjukkannya, bukan?).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
