INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ffc99a15-facc-4c1b-ae37-6a5a99886144', 'カッパは、日本古来のようかいです。', 'Kappa adalah yokai Jepang kuno.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ffc99a15-facc-4c1b-ae37-6a5a99886144', '古来、この池は、「ワニカニの池」という名まえでしられていました。', 'Pada zaman dahulu, kolam ini dikenal dengan nama “Kolam WaniKani”.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ffc99a15-facc-4c1b-ae37-6a5a99886144', 'トイレは、古来から現代へと受け継がれてきた素晴らしい発明品だ。', 'Toilet adalah penemuan luar biasa yang telah diwariskan sejak zaman kuno hingga saat ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('80a9abd0-face-4ef8-a29a-f6fae5896e07', 'vocabulary', '入社', '入社', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ketika Anda memasuki sebuah perusahaan, Anda sebenarnya bergabung dengan sebuah perusahaan. Selamat datang, rekrutan baru. Bersiaplah untuk dikaburkan!', 'Ketika Anda memasuki sebuah perusahaan, Anda sebenarnya bergabung dengan sebuah perusahaan. Selamat datang, rekrutan baru. Bersiaplah untuk dikaburkan!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
