INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('80a9abd0-face-4ef8-a29a-f6fae5896e07', 'にゅうしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('80a9abd0-face-4ef8-a29a-f6fae5896e07', 'この会社には、四月に入社しました。', 'Saya bergabung dengan perusahaan ini pada bulan April.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('80a9abd0-face-4ef8-a29a-f6fae5896e07', 'トーフグの入社しけんはグーグルの入社しけんよりもむずかしい。', 'Ujian kerja Tofugu lebih sulit dibandingkan ujian Google.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('80a9abd0-face-4ef8-a29a-f6fae5896e07', '大学を卒業したらすぐに、大きな金融機関に入社するか、アメリカ合衆国の大統領になれたらいいなと思っている。', 'Segera setelah saya lulus kuliah, saya berharap untuk bergabung dengan perusahaan keuangan besar atau menjadi presiden Amerika Serikat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('86db5546-e91f-4601-960e-3fba522bc18d', 'vocabulary', '公社', '公社', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Perusahaan publik adalah perusahaan yang dikelola pemerintah atau perusahaan milik pemerintah. Dengan kata lain, ini adalah perusahaan yang dijalankan oleh pemerintah pusat atau daerah untuk kepentingan masyarakat.', 'Perusahaan publik adalah perusahaan yang dikelola pemerintah atau perusahaan milik pemerintah. Dengan kata lain, ini adalah perusahaan yang dijalankan oleh pemerintah pusat atau daerah untuk kepentingan masyarakat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
