INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86db5546-e91f-4601-960e-3fba522bc18d', 'たしか、かれは公社ではたらいています。', 'Jika saya ingat dengan benar, dia bekerja di perusahaan yang dikelola pemerintah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86db5546-e91f-4601-960e-3fba522bc18d', 'このりょきゃくてつどうは、みなみアフリカりょきゃくてつどう公社がうんえいしています。', 'Layanan kereta penumpang ini dioperasikan oleh Badan Kereta Penumpang Afrika Selatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('86db5546-e91f-4601-960e-3fba522bc18d', '4月1日に国営公社である日本郵政公社が業務を開始したが、エイプリルフールのジョークではなかった。', 'Pada tanggal 1 April, sebuah perusahaan milik pemerintah bernama Japan Post dibuka untuk bisnis dan itu bukan lelucon April Mop.') ON CONFLICT DO NOTHING;
