INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a8f03f0-aa0d-4485-b2c2-e21581d7f499', '本社はとうきょうにあります。', 'Kantor pusatnya berada di Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a8f03f0-aa0d-4485-b2c2-e21581d7f499', '月よう日に、トーフグの本社におじゃましてきました。', 'Pada hari Senin, saya mengunjungi Markas Besar Tofugu.') ON CONFLICT DO NOTHING;
