INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cf16c4a0-d77d-450d-967b-491cff3fc078', 'あの子は次の行どうがよそくできないから、安心できないのよね。', 'Saya tidak pernah tahu apa yang akan dilakukan anak itu selanjutnya, jadi saya tidak bisa tenang.') ON CONFLICT DO NOTHING;
