INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0c9c46d2-422c-4b60-a67c-db852344f735', 'vocabulary', '不安', '不安', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Saat Anda tidak rileks, apa yang Anda rasakan? Kegelisahan adalah apa yang Anda rasakan.', 'Saat Anda tidak rileks, apa yang Anda rasakan? Kegelisahan adalah apa yang Anda rasakan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
