INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c9c46d2-422c-4b60-a67c-db852344f735', 'ごうかくしているか不安です。', 'Saya cemas untuk lulus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c9c46d2-422c-4b60-a67c-db852344f735', '出さんを目前に不安な気もちでいっぱいです。', 'Saya sangat gugup dengan persalinan yang akan datang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c9c46d2-422c-4b60-a67c-db852344f735', 'あの殺人事件を目撃してからというもの、不安を取り除くことができない。', 'Sejak saya menyaksikan pembunuhan itu, saya belum bisa menghilangkan perasaan cemas ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('789174f6-9c76-4bc3-9600-7f612e664752', 'vocabulary', '有る', '有る', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti memiliki, jadi versi kata kerjanya berarti memiliki. Arti alternatifnya adalah ada meskipun ini hanya mengacu pada benda mati yang tidak hidup, bukan benda bergerak dan hidup. Jadi sebenarnya, ini mirip dengan "memiliki" juga.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('789174f6-9c76-4bc3-9600-7f612e664752', 'Untuk Memiliki', true) ON CONFLICT DO NOTHING;
