INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('789174f6-9c76-4bc3-9600-7f612e664752', 'マヨネーズなら、まだ少し有ります。', 'Kami masih memiliki sedikit mayones.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('789174f6-9c76-4bc3-9600-7f612e664752', '一じかんに一本しかでん車は有りません。', 'Hanya ada satu kereta per jam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('789174f6-9c76-4bc3-9600-7f612e664752', '彼の家には金も有るが、屋根の上に銀も有る。', 'Ada emas di rumahnya dan perak di atapnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('81578233-8e09-4373-a434-7b12f7e5bdfe', 'vocabulary', '有名', '有名', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ketika Anda memiliki nama (yang dikenal orang) atau Anda terkenal, kemungkinan besar Anda adalah seseorang yang terkenal.', 'Ketika Anda memiliki nama (yang dikenal orang) atau Anda terkenal, kemungkinan besar Anda adalah seseorang yang terkenal.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
