INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81578233-8e09-4373-a434-7b12f7e5bdfe', 'いえの近くに、有名なすしやがあります。', 'Ada restoran sushi terkenal di dekat rumah saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81578233-8e09-4373-a434-7b12f7e5bdfe', 'このきじはトーフグを一やくちょう有名にした。', 'Artikel ini tiba-tiba membuat Tofugu menjadi sangat populer.') ON CONFLICT DO NOTHING;
