INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('54234c04-d9c7-4c0a-a225-1380a4a4f56e', 'vocabulary', '死体', '死体', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kanji untuk kematian dan tubuh disatukan menghasilkan mayat. Semoga Anda tidak terlalu sering menggunakan atau melihat vocab ini.', 'Kanji untuk kematian dan tubuh disatukan menghasilkan mayat. Semoga Anda tidak terlalu sering menggunakan atau melihat vocab ini.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
