INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54234c04-d9c7-4c0a-a225-1380a4a4f56e', 'だれが死体を見つけましたか。', 'Siapa yang menemukan mayat itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54234c04-d9c7-4c0a-a225-1380a4a4f56e', 'だれが死体いきのようぎでたいほされたって？', 'Menurut Anda siapa yang ditangkap karena meninggalkan mayat?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54234c04-d9c7-4c0a-a225-1380a4a4f56e', '私が初めて死体を見たのは、六歳の時です。', 'Pertama kali saya melihat mayat adalah ketika saya berumur enam tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cb3da577-8ee5-40e7-b016-58dee46253d0', 'vocabulary', '社長', '社長', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Pemimpin perusahaan adalah presiden, manajer, atau direktur perusahaan. Pastikan untuk menyapa 社長 Anda dengan ucapan selamat pagi yang hangat saat dia tersandung!', 'Pemimpin perusahaan adalah presiden, manajer, atau direktur perusahaan. Pastikan untuk menyapa 社長 Anda dengan ucapan selamat pagi yang hangat saat dia tersandung!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
