INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cb3da577-8ee5-40e7-b016-58dee46253d0', '社長は会ぎ中です。', 'Presiden perusahaan sedang rapat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cb3da577-8ee5-40e7-b016-58dee46253d0', 'あの人気サービスのねだんを下げるなんて、トーフグの社長はどうかしてるよ。', 'Presiden Tofugu gila-gilaan menurunkan harga layanan populer itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cb3da577-8ee5-40e7-b016-58dee46253d0', '全社員は社長のことを嫌っているが、私は単に彼は少し意地悪なだけだと思っている。', 'Semua rekan kerjaku membenci atasanku, tapi menurutku dia sedikit jahat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3029f190-3702-468c-878c-bec340270ff8', 'vocabulary', '同時', '同時', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Waktu yang sama? Oke, katakanlah secara bersamaan apa arti kata ini menurut kami. Ups, saya baru saja mengatakannya, maaf.', 'Waktu yang sama? Oke, katakanlah secara bersamaan apa arti kata ini menurut kami. Ups, saya baru saja mengatakannya, maaf.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
