INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa570062-9250-4e52-bd17-a4e0315dd45f', 'かれは、心身ともに、つかれきっていたんだと思います。', 'Saya pikir tubuh dan pikirannya sama-sama lelah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa570062-9250-4e52-bd17-a4e0315dd45f', '取りえは、心身ともにけん全であることだけです。', 'Satu-satunya kekuatan saya adalah pikiran dan tubuh yang sehat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa570062-9250-4e52-bd17-a4e0315dd45f', 'ヨガは、心身共にとても健康にしてくれる。', 'Yoga sangat baik untuk kesehatan tubuh dan pikiran Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b1c3e423-f288-4320-bae8-02dcc75a10fd', 'vocabulary', '身体', '身体', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Tubuh seseorang. Ini mengacu pada kata yang sangat umum yaitu tubuh. Seperti dalam, "tubuh manusia" atau sesuatu seperti itu. Ini juga bisa merujuk pada kesehatan.', 'Tubuh seseorang. Ini mengacu pada kata yang sangat umum yaitu tubuh. Seperti dalam, "tubuh manusia" atau sesuatu seperti itu. Ini juga bisa merujuk pada kesehatan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
