INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b1c3e423-f288-4320-bae8-02dcc75a10fd', '明日は、学校で身体そくていがあります。', 'Besok akan ada pengukuran tubuh di sekolah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b1c3e423-f288-4320-bae8-02dcc75a10fd', 'この図しょかんには、身体しょうがいしゃがつかえるトイレはありますか？', 'Apakah ada toilet yang dapat diakses oleh penyandang disabilitas di perpustakaan ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b1c3e423-f288-4320-bae8-02dcc75a10fd', '空こうで、まやくをかくしもっていないか、身体けんさをされました。', 'Di bandara, mereka menggeledah saya untuk mencari obat-obatan terlarang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('28a1b7f9-25f3-4175-853c-1e7f39c0a297', 'vocabulary', '会話', '会話', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Saat Anda bertemu dan berbicara dengan orang lain, Anda sedang melakukan percakapan.', 'Saat Anda bertemu dan berbicara dengan orang lain, Anda sedang melakukan percakapan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
