INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('28a1b7f9-25f3-4175-853c-1e7f39c0a297', 'かいわ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28a1b7f9-25f3-4175-853c-1e7f39c0a297', '男の人と女の人が、大学のろう下で会話をしています。', 'Seorang pria dan seorang wanita sedang mengobrol di lorong universitas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28a1b7f9-25f3-4175-853c-1e7f39c0a297', 'ペースのはやい日本ごの会話は、まだりかい出来ません。', 'Saya belum bisa memahami dialog Jepang yang bertempo cepat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28a1b7f9-25f3-4175-853c-1e7f39c0a297', 'どうして私達の会話はいつも野球についてなのでしょうか？', 'Mengapa percakapan kami selalu tentang baseball?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('54f8ef68-fca5-4d36-8a62-7eff216da5d9', 'vocabulary', '別の', '別の', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Tanda の ada untuk menunjukkan bahwa itu adalah perbedaan dari sesuatu. Misalnya, ini seperti mengatakan "______ yang terpisah" atau "______ yang berbeda" atau "______ yang lain". 別 dengan sendirinya berarti terpisah, berbeda, atau lainnya.', 'Tanda の ada untuk menunjukkan bahwa itu adalah perbedaan dari sesuatu. Misalnya, ini seperti mengatakan "______ yang terpisah" atau "______ yang berbeda" atau "______ yang lain". 別 dengan sendirinya berarti terpisah, berbeda, atau lainnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
