INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54f8ef68-fca5-4d36-8a62-7eff216da5d9', '別のアプローチをトライしてみない？', 'Mengapa kita tidak mencoba pendekatan yang berbeda?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54f8ef68-fca5-4d36-8a62-7eff216da5d9', 'これとそれは、別のもんだいだと思います。', 'Menurut saya ini dan itu adalah persoalan yang terpisah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54f8ef68-fca5-4d36-8a62-7eff216da5d9', '私は家を二軒所有している。三ヶ月ほど前に購入した場所と、谷底にもう一件別の家がある。', 'Saya memiliki dua rumah. Saya membeli tempat ini sekitar tiga bulan lalu dan saya memiliki tempat lain di lembah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e5a741d8-7f1f-4acc-afc2-9d26a6065461', 'vocabulary', '別に', '別に', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Jika seseorang bertanya apakah Anda ingin lutut terpisah (に), Anda akan menjawab tidak terlalu. Maksud saya, Anda belum pernah memikirkannya, tapi apakah Anda benar-benar membutuhkan lebih banyak lutut? Tidak juga...
