INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e5a741d8-7f1f-4acc-afc2-9d26a6065461', 'べつに', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5a741d8-7f1f-4acc-afc2-9d26a6065461', '温かいものはふくろを別にしてください。', 'Bisakah Anda menggunakan tas terpisah untuk barang hangat?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5a741d8-7f1f-4acc-afc2-9d26a6065461', '別に会社で人間関係に苦労はしてないよ。', 'Saya tidak terlalu kesulitan menangani hubungan antarmanusia di tempat kerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5a741d8-7f1f-4acc-afc2-9d26a6065461', '「おお、フグ。最近どうよ？」「別に変わりないね。ワニ君、君はどうだい？」', '"Hei Fugu! Apa yang kamu lakukan akhir-akhir ini?" "Tidak ada yang khusus. Bagaimana denganmu, Wani?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2d6d56ff-986c-4a1e-85ad-cead618ef076', 'vocabulary', '別人', '別人', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Orang yang terpisah adalah seseorang yang berbeda dari sebelumnya. Aku melihatmu setahun yang lalu dan kamu adalah orang lain. Sekarang Anda menjadi orang yang berbeda, dalam cara yang baik! Anda seorang pria yang berubah.', 'Orang yang terpisah adalah seseorang yang berbeda dari sebelumnya. Aku melihatmu setahun yang lalu dan kamu adalah orang lain. Sekarang Anda menjadi orang yang berbeda, dalam cara yang baik! Anda seorang pria yang berubah.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
