INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2d6d56ff-986c-4a1e-85ad-cead618ef076', 'べつじん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2d6d56ff-986c-4a1e-85ad-cead618ef076', 'コウイチはお酒を止めてから、すっかり別人になったね。', 'Koichi adalah pria yang berubah sejak dia berhenti minum.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2d6d56ff-986c-4a1e-85ad-cead618ef076', '友だちだと思って声をかけたら、かん全に別人だった。', 'Saya pikir itu adalah teman saya dan menyapa, tapi itu adalah orang yang sama sekali berbeda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2d6d56ff-986c-4a1e-85ad-cead618ef076', 'コウイチは昔はAKB48をよくディスっていたのに、今はすっかり大ファンになっちまった。まるで別人のようだよ。', 'Koichi dulu sering menjelek-jelekkan AKB48, tapi sekarang dia menjadi penggemar berat AKB48. Seolah-olah dia orang yang berbeda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ee1ffb48-7c55-4f55-aa54-8fe8defbb3fa', 'vocabulary', '別々', '別々', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ketika Anda berpisah, Anda menempatkan segala sesuatunya di wilayahnya masing-masing. Anda menandainya secara terpisah dan satu per satu.', 'Ketika Anda berpisah, Anda menempatkan segala sesuatunya di wilayahnya masing-masing. Anda menandainya secara terpisah dan satu per satu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ee1ffb48-7c55-4f55-aa54-8fe8defbb3fa', 'Secara terpisah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ee1ffb48-7c55-4f55-aa54-8fe8defbb3fa', 'Individually', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ee1ffb48-7c55-4f55-aa54-8fe8defbb3fa', 'べつべつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee1ffb48-7c55-4f55-aa54-8fe8defbb3fa', '二人はふた子だが、いつもそれぞれ別々なことを考えてる。', 'Mereka kembar, tapi mereka berpikir secara terpisah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee1ffb48-7c55-4f55-aa54-8fe8defbb3fa', 'サボテンとは別々にしてうえて下さい。', 'Silakan tanam ini secara terpisah dari kaktus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee1ffb48-7c55-4f55-aa54-8fe8defbb3fa', '「私達、本当に別々の道を進まなきゃいけないの？」「ああ。でもまたすぐ会えるさ。」', '"Sekarang apakah kita benar-benar harus berpisah?" "Ya, tapi aku yakin kita akan segera bertemu lagi."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('38924381-e7e5-4fa8-baf3-b4ff53b871a1', 'vocabulary', '小文字', '小文字', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda tahu bahwa 文字 berarti "huruf". Jadi, apa itu "huruf kecil"? Itu akan menjadi huruf kecil.', 'Anda tahu bahwa 文字 berarti "huruf". Jadi, apa itu "huruf kecil"? Itu akan menjadi huruf kecil.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
