INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('38924381-e7e5-4fa8-baf3-b4ff53b871a1', 'どうやって小文字と大文字を切りかえますか。', 'Bagaimana cara beralih dari huruf kecil ke huruf besar?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('38924381-e7e5-4fa8-baf3-b4ff53b871a1', 'パスワードには、かならず大文字、小文字、すう字を一つい上つかってください。', 'Kata sandi harus mengandung setidaknya satu huruf besar, satu huruf kecil, dan satu angka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('38924381-e7e5-4fa8-baf3-b4ff53b871a1', '君のEメールアドレスって、全部小文字なの？本当に？ちょっとおかしいんじゃないの？', 'Apakah alamat email Anda menggunakan huruf kecil semua? Benarkah? Apakah kamu gila?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cc18bddc-e14c-41ce-9808-fdd30144fe19', 'vocabulary', '冬休み', '冬休み', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Istirahat musim dingin! Tunggu, tidak ada yang menyebutnya begitu. Ini adalah liburan musim dingin atau liburan musim dingin.', 'Istirahat musim dingin! Tunggu, tidak ada yang menyebutnya begitu. Ini adalah liburan musim dingin atau liburan musim dingin.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cc18bddc-e14c-41ce-9808-fdd30144fe19', 'Liburan Musim Dingin', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cc18bddc-e14c-41ce-9808-fdd30144fe19', 'Winter Break', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cc18bddc-e14c-41ce-9808-fdd30144fe19', 'Winter Vacation', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('cc18bddc-e14c-41ce-9808-fdd30144fe19', 'ふゆやすみ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc18bddc-e14c-41ce-9808-fdd30144fe19', '冬休みに、かぞくで山の中のホテルにとまりました。', 'Selama liburan musim dingin, keluarga saya menginap di sebuah hotel di pegunungan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc18bddc-e14c-41ce-9808-fdd30144fe19', '冬休みは子どもたちがいえで兄弟げんかばっかりしていて大へんでした。', 'Liburan musim dingin cukup sulit karena anak-anak saya sering bertengkar di rumah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc18bddc-e14c-41ce-9808-fdd30144fe19', '冬休みは、毎日一日中ジョギングをしていました。', 'Selama liburan musim dingin, saya jogging setiap hari, sepanjang hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('852c7c14-8884-4b77-8c65-e27d6d23c724', 'vocabulary', '方言', '方言', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Cara Anda mengatakan sesuatu bisa diterjemahkan sebagai aksen Anda... tapi ini jauh lebih besar. Ini adalah keseluruhan "cara" berbicara. Ini adalah dialek. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('852c7c14-8884-4b77-8c65-e27d6d23c724', 'Dialek', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('852c7c14-8884-4b77-8c65-e27d6d23c724', 'ほうげん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('852c7c14-8884-4b77-8c65-e27d6d23c724', '方言のじしょを作っています。', 'Saya sedang membuat kamus dialek.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('852c7c14-8884-4b77-8c65-e27d6d23c724', 'ああっもうっ！かれしの方言がうつっちゃってるずら。', 'Berengsek! Dialek pacar saya telah menular ke saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('852c7c14-8884-4b77-8c65-e27d6d23c724', '私の国の東側出身の人達は変わった方言で喋るので、彼らが何を言っているのか全く分かりません。', 'Orang-orang dari bagian timur negara saya menggunakan dialek yang aneh sehingga mereka tidak mungkin memahaminya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5e7688f3-ae65-4d67-95e1-c63e2b87de3e', 'vocabulary', '手作り', '手作り', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Sesuatu yang dibuat dengan tangan berarti buatan tangan!', 'Sesuatu yang dibuat dengan tangan berarti buatan tangan!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
