INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5e7688f3-ae65-4d67-95e1-c63e2b87de3e', 'てづくり', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e7688f3-ae65-4d67-95e1-c63e2b87de3e', 'このテーブルは、林さんの手作りです。', 'Meja ini buatan tangan oleh Hayashi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e7688f3-ae65-4d67-95e1-c63e2b87de3e', '毎日手作りのバランスのいい食じをとるようにしています。', 'Saya mencoba menjalani pola makan buatan sendiri yang seimbang setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e7688f3-ae65-4d67-95e1-c63e2b87de3e', '手作りのプレゼントは、どれだけ暇な時間があるかってことがバレてしまうので、結構怖い。', 'Hadiah buatan tangan cukup menakutkan karena menunjukkan bahwa Anda memiliki terlalu banyak waktu luang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fa9aa47f-a751-4eed-8a1f-e4dfb31c555e', 'vocabulary', '近づく', '近づく', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Karena kata ini diakhiri dengan bunyi う, Anda dapat mengetahui kemungkinan itu adalah kata kerja. Bagian kanji artinya dekat. Versi kata kerjanya adalah mendekat, mendekat, atau mendekat. Pada dasarnya, gagasan umumnya adalah Anda semakin dekat dengan sesuatu. Anda menjadi lebih dekat. Anda mendekat.', 'Karena kata ini diakhiri dengan bunyi う, Anda dapat mengetahui kemungkinan itu adalah kata kerja. Bagian kanji artinya dekat. Versi kata kerjanya adalah mendekat, mendekat, atau mendekat. Pada dasarnya, gagasan umumnya adalah Anda semakin dekat dengan sesuatu. Anda menjadi lebih dekat. Anda mendekat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
