INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa9aa47f-a751-4eed-8a1f-e4dfb31c555e', 'カメラマンが近づくとカメはにげてしまった。', 'Saat juru kamera mendekatinya, penyu tersebut lari.') ON CONFLICT DO NOTHING;
