INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67bad6a7-6e4c-4fb0-b040-4396baa260fc', 'おいしいマカロニチーズの作り方を教えてください。', 'Tolong ajari saya cara membuat makaroni dan keju yang enak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67bad6a7-6e4c-4fb0-b040-4396baa260fc', '麦茶の作り方には、おゆでわかしながらに出す方ほう、ふっとうさせたおゆでジワジワおゆ出しする方ほう、つめたい水でジワジワ水出しする方ほうの三しゅるいありますが、それぞれメリットデメリットがあります。', 'Ada tiga cara membuat teh jelai; merendamnya dalam air mendidih, merendamnya perlahan dalam air matang, dan merendamnya perlahan dalam air dingin, dan masing-masing memiliki kelebihan dan kekurangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67bad6a7-6e4c-4fb0-b040-4396baa260fc', '手裏剣の作り方を知りたいですか？', 'Ingin tahu cara membuat bintang ninja?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('466e7394-14ed-4417-9b40-5081b575f0c1', 'vocabulary', '出会う', '出会う', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda keluar dari rumah Anda dan bertemu seseorang. Anda tidak bermaksud untuk bertemu mereka, tetapi hal itu tetap terjadi. Itu sebabnya kata ini berarti bertemu secara kebetulan.', 'Anda keluar dari rumah Anda dan bertemu seseorang. Anda tidak bermaksud untuk bertemu mereka, tetapi hal itu tetap terjadi. Itu sebabnya kata ini berarti bertemu secara kebetulan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
