INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b56a8c95-175d-4f22-9fd4-57f8fc56d9b0', '昨日の夜、バーデビューしちゃった。私もちょっとずつ大人の階段登ってるって感じ？', 'Saya pergi ke bar untuk pertama kalinya tadi malam. Saya merasa seperti saya perlahan menjadi dewasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fa5983c4-4a9b-4a0b-8010-0c2737aba61e', 'vocabulary', '私立', '私立', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Tempatku berdiri adalah area pribadiku. Pikirkan tentang "lingkaran ruang pribadi". Di sinilah Anda berdiri ditambah jarak satu lengan. Area ini sangat pribadi bagi Anda. Siapa yang tahu apa yang Anda lakukan di area pribadi Anda.', 'Tempatku berdiri adalah area pribadiku. Pikirkan tentang "lingkaran ruang pribadi". Di sinilah Anda berdiri ditambah jarak satu lengan. Area ini sangat pribadi bagi Anda. Siapa yang tahu apa yang Anda lakukan di area pribadi Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
