INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c896604-435f-43ba-8b6e-2e52842cba07', '私立大学は公立大学よりじゅ業料が高いです。', 'Biaya kuliah di perguruan tinggi swasta lebih mahal dibandingkan dengan perguruan tinggi negeri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c896604-435f-43ba-8b6e-2e52842cba07', 'わせ田大学は日本の有名な私立大学です。', 'Universitas Waseda adalah universitas swasta terkenal di Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c896604-435f-43ba-8b6e-2e52842cba07', 'あの出火した私立大学は、私が通っている学校だよ。', 'Perguruan tinggi swasta yang sedang on fire adalah perguruan tinggi yang saya ikuti saat ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('965a077b-c27e-49a0-8499-08c110015d6d', 'vocabulary', '私大', '私大', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda tahu bagaimana 私 bisa berarti pribadi dan bagaimana 大 adalah bagian pertama dari 大学? Nah, gabungkan keduanya dan Anda akan mendapatkan versi singkat dari perguruan tinggi swasta atau universitas swasta.', 'Anda tahu bagaimana 私 bisa berarti pribadi dan bagaimana 大 adalah bagian pertama dari 大学? Nah, gabungkan keduanya dan Anda akan mendapatkan versi singkat dari perguruan tinggi swasta atau universitas swasta.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
