INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc680f63-748b-4726-a57a-f0b4ce6bb6f3', 'リストラで、身も心もズタズタです。', 'Karena PHK saya, fisik dan mental saya terkoyak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc680f63-748b-4726-a57a-f0b4ce6bb6f3', 'この魚の身はたん白でおいしいね。', 'Daging ikan ini ringan dan enak bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc680f63-748b-4726-a57a-f0b4ce6bb6f3', '現金は常に身につけておく方がいい。', 'Anda harus selalu membawa uang tunai.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5d633797-ca8c-4ae7-b77d-1c2bf975fd3c', 'vocabulary', '社会', '社会', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Jangan bingung dengan 会社, yang merupakan perusahaan, inilah masyarakat. Ketika sebuah perusahaan bertemu bersama, itu seperti sekelompok orang, yang berada dalam kelompok, berkumpul untuk hidup di satu dunia. Itu adalah masyarakat.', 'Jangan bingung dengan 会社, yang merupakan perusahaan, inilah masyarakat. Ketika sebuah perusahaan bertemu bersama, itu seperti sekelompok orang, yang berada dalam kelompok, berkumpul untuk hidup di satu dunia. Itu adalah masyarakat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5d633797-ca8c-4ae7-b77d-1c2bf975fd3c', 'Masyarakat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5d633797-ca8c-4ae7-b77d-1c2bf975fd3c', 'しゃかい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d633797-ca8c-4ae7-b77d-1c2bf975fd3c', '今家を出ても、社会のじゅぎょうに間にあわないと思います。', 'Bahkan jika aku meninggalkan rumah sekarang, aku pikir aku mungkin akan terlambat untuk pelajaran IPS.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d633797-ca8c-4ae7-b77d-1c2bf975fd3c', '国さい社会の一員として、めしテロにはだんじてくっしません。', 'Sebagai anggota masyarakat internasional, saya tidak akan menyerah pada pornografi makanan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d633797-ca8c-4ae7-b77d-1c2bf975fd3c', '社会問題として、若者がお葬式で自分撮りをすることについて考える必要がある。', 'Sebagai masyarakat, kita perlu khawatir terhadap generasi muda yang melakukan ‘selfie’ di pemakaman.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('317abc16-85d4-475e-9a09-230552eb9ff8', 'vocabulary', '言語', '言語', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Saat Anda mengucapkan kata-kata dalam suatu bahasa, Anda sedang berbicara dalam suatu bahasa. Tidak yakin bahasa apa itu, tapi karena Anda mengatakannya, itu pasti nyata.', 'Saat Anda mengucapkan kata-kata dalam suatu bahasa, Anda sedang berbicara dalam suatu bahasa. Tidak yakin bahasa apa itu, tapi karena Anda mengatakannya, itu pasti nyata.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
