INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('caa109d7-57f0-444f-b173-30cfea742a26', ' 木のはが地上におちた。', 'Daunnya jatuh ke tanah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('caa109d7-57f0-444f-b173-30cfea742a26', 'コウイチは地上1kmの所に、ひみつき地をもっている。', 'Koichi memiliki Pangkalan Rahasia 1 km di atas tanah.') ON CONFLICT DO NOTHING;
