INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b4ee7a19-cd26-4647-811c-a32ab65d1285', 'vocabulary', '足す', '足す', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ingat 足りる? Itu berarti "menjadi cukup". Bagaimana Anda bisa membuat sesuatu menjadi cukup? Anda terus menambahkan sesuatu ke tumpukan sampai Anda mencapai titik di mana jumlahnya cukup! Itu sebabnya kata kerjanya adalah menambahkan sesuatu, karena Anda terus menambahkan sesuatu sampai Anda 足りる.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b4ee7a19-cd26-4647-811c-a32ab65d1285', 'Untuk Menambahkan Sesuatu', true) ON CONFLICT DO NOTHING;
