INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4ee7a19-cd26-4647-811c-a32ab65d1285', '三足す二は五です。', 'Tiga tambah dua adalah lima.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4ee7a19-cd26-4647-811c-a32ab65d1285', 'このスープ、もう少し水を足した方がいいんじゃないかな。', 'Mungkin lebih baik menambahkan lebih banyak air ke dalam sup ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4ee7a19-cd26-4647-811c-a32ab65d1285', 'ここにもう少し文章を書き足すことはできますか？', 'Bisakah Anda menambahkan sedikit lagi pada kalimat ini di sini?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6a3dae58-c6b3-4a92-9227-c20dd69509b0', 'vocabulary', '別れる', '別れる', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya terpisah, jadi bisa ditebak maksudnya memisahkan atau membagi.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya terpisah, jadi bisa ditebak maksudnya memisahkan atau membagi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
