INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a3dae58-c6b3-4a92-9227-c20dd69509b0', 'コウイチ子はコウイチと別れてビエトと付き合いました。', 'Koichiko berpisah dari Koichi dan mulai berkencan dengan Viet.') ON CONFLICT DO NOTHING;
