INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0223917c-3053-4d36-a0a9-6602c54ca12a', 'きんようびの夜に、女子会をします。', 'Saya mengadakan pesta khusus perempuan pada Jumat malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0223917c-3053-4d36-a0a9-6602c54ca12a', 'そのメンバーの会はとてもおも白そうですね。', 'Pertemuan dengan para anggota tersebut terdengar sangat menarik.') ON CONFLICT DO NOTHING;
