INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2f89818d-c3f8-4681-91c1-7630d30f187f', 'vocabulary', '早く', '早く', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah versi kata keterangan dari kanji awal. Ini adalah hal kecil yang dapat Anda gunakan untuk memulai kalimat yang mengatakan Anda melakukan sesuatu lebih awal atau cepat.', 'Ini adalah versi kata keterangan dari kanji awal. Ini adalah hal kecil yang dapat Anda gunakan untuk memulai kalimat yang mengatakan Anda melakukan sesuatu lebih awal atau cepat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
