INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5ab43d6a-477e-468c-88ff-d4104450be8c', 'vocabulary', '考古学', '考古学', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kalau sering terpikir untuk mempelajari benda-benda kuno, namanya arkeologi. Semua arkeologi melibatkan pemikiran tentang hal-hal lama, setidaknya sedikit.', 'Kalau sering terpikir untuk mempelajari benda-benda kuno, namanya arkeologi. Semua arkeologi melibatkan pemikiran tentang hal-hal lama, setidaknya sedikit.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
