INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d716860b-fb39-47cc-a0aa-f6456a294cc4', '地中は、冬にはあたたかく、なつはつめたいです。', 'Di bawah tanah hangat di musim dingin dan dingin di musim panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d716860b-fb39-47cc-a0aa-f6456a294cc4', '多くのみずうみは、地中の水ろでつながっています。', 'Banyak danau yang dihubungkan oleh saluran bawah tanah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d716860b-fb39-47cc-a0aa-f6456a294cc4', '地中の温度を測るにはどうすればいいですか。', 'Apa yang harus saya lakukan untuk mengukur suhu di bawah tanah?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('12c37eb5-cf5e-489b-9f33-10cf06b3fe8e', 'vocabulary', '一体', '一体', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Oke, jadi yang ini aneh sekali, maaf. Masing-masing dari kita hanya mendapatkan satu tubuh seumur hidup, bukan? Ya, apa-apaan ini! Bagaimana jika saya menginginkan lebih dari satu tubuh. Mari kita semua marah tentang hal ini bersama-sama.', 'Oke, jadi yang ini aneh sekali, maaf. Masing-masing dari kita hanya mendapatkan satu tubuh seumur hidup, bukan? Ya, apa-apaan ini! Bagaimana jika saya menginginkan lebih dari satu tubuh. Mari kita semua marah tentang hal ini bersama-sama.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
