INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('12c37eb5-cf5e-489b-9f33-10cf06b3fe8e', '一体どうなっているんだ。', 'Apa yang sedang terjadi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('12c37eb5-cf5e-489b-9f33-10cf06b3fe8e', '「あいとにくしみはひょうり一体」って、一体全体どういういみなんだ！？', 'Apa maksudnya, "Ada garis tipis antara cinta dan benci"?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('12c37eb5-cf5e-489b-9f33-10cf06b3fe8e', '一体俺が何をしたって言うんだよ？', 'Apa yang kamu bilang aku lakukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4ca81e1b-35e3-4dd0-a682-0182dd927933', 'vocabulary', '生地', '生地', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kehidupan yang keluar dari bumi terdiri dari berbagai jenis bahan. Kadang kain, kadang adonan, tapi semuanya harus terbuat dari sesuatu.', 'Kehidupan yang keluar dari bumi terdiri dari berbagai jenis bahan. Kadang kain, kadang adonan, tapi semuanya harus terbuat dari sesuatu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4ca81e1b-35e3-4dd0-a682-0182dd927933', 'Bahan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4ca81e1b-35e3-4dd0-a682-0182dd927933', 'Cloth', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4ca81e1b-35e3-4dd0-a682-0182dd927933', 'Fabric', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4ca81e1b-35e3-4dd0-a682-0182dd927933', 'Dough', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4ca81e1b-35e3-4dd0-a682-0182dd927933', 'Batter', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4ca81e1b-35e3-4dd0-a682-0182dd927933', 'きじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ca81e1b-35e3-4dd0-a682-0182dd927933', 'マリメッコの生地でクッションを作りました。', 'Saya membuat bantal dari kain Marimekko.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ca81e1b-35e3-4dd0-a682-0182dd927933', 'このカーテンは、パラシュート生地でできています。', 'Tirai ini terbuat dari bahan parasut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ca81e1b-35e3-4dd0-a682-0182dd927933', '冷凍のパイ生地を買ってきてください。', 'Silakan beli potongan beku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('39832552-1b81-4155-8aea-0c5ae3a308b7', 'vocabulary', '別', '別', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('39832552-1b81-4155-8aea-0c5ae3a308b7', 'Berbeda', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('39832552-1b81-4155-8aea-0c5ae3a308b7', 'Separate', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('39832552-1b81-4155-8aea-0c5ae3a308b7', 'べつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('39832552-1b81-4155-8aea-0c5ae3a308b7', 'コウイチが、別の女と歩いているところを見たの。', 'Saya melihat Koichi berjalan dengan gadis yang berbeda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('39832552-1b81-4155-8aea-0c5ae3a308b7', 'それとこれとは話が別だろう。', 'Ini dan itu adalah dua cerita yang berbeda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('39832552-1b81-4155-8aea-0c5ae3a308b7', 'その場合は別として、このやり方で男女を別にするのは通じょうもんだいありません。', 'Selain itu, biasanya tidak masalah jika memisahkan jenis kelamin dengan cara ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e5869fca-50d9-4494-b10b-752becd8fe9c', 'vocabulary', '大体', '大体', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Jika yang Anda lihat hanyalah bagian besar dari suatu benda, maka Anda hanya akan mendapatkan gambaran umum tentang benda tersebut. Anda akan dapat mengatakan bahwa secara umum ini adalah cara tertentu, tetapi itu saja. Anda akan mendapatkan intinya, tapi tidak lebih.', 'Jika yang Anda lihat hanyalah bagian besar dari suatu benda, maka Anda hanya akan mendapatkan gambaran umum tentang benda tersebut. Anda akan dapat mengatakan bahwa secara umum ini adalah cara tertentu, tetapi itu saja. Anda akan mendapatkan intinya, tapi tidak lebih.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e5869fca-50d9-4494-b10b-752becd8fe9c', 'Umumnya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e5869fca-50d9-4494-b10b-752becd8fe9c', 'About', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e5869fca-50d9-4494-b10b-752becd8fe9c', 'General', false) ON CONFLICT DO NOTHING;
